components.css:
.wf-text-paragraph {
  font-family: var(--wf-font-serif, Georgia, serif);
  font-size: clamp(1.125rem, 1.05rem + 0.375vw, 1.25rem);
  line-height: 1.6;
  color: var(--wf-ink, #353431);
}
.wf-text-link {
  color: inherit;
  text-decoration-line: underline;
  text-decoration-style: dotted;
  text-decoration-thickness: 0.06em;
  text-underline-offset: 0.14em;
  transition: color var(--wf-motion-hover, 180ms) var(--wf-ease, cubic-bezier(0.333333, 0, 0.666667, 1));
}
.wf-text-link:hover,
.wf-text-link:focus-visible {
  color: var(--wf-ink, #353431);
  text-decoration-style: solid;
}
.wf-text-link:focus-visible {
  outline: var(--wf-focus-width, 1px) solid currentColor;
  outline-offset: var(--wf-focus-offset, 3px);
}
[data-theme="night"] .wf-text-link:hover,
[data-theme="night"] .wf-text-link:focus-visible {
  color: var(--wf-night-bright, #ffffff);
}

.wf-action-link {
  display: inline-flex;
  align-items: baseline;
  gap: var(--wf-space-xs, 6px);
  color: var(--wf-ink, #353431);
  font-family: var(--wf-font-mono, ui-monospace, monospace);
  font-size: 0.8125rem;
  font-weight: var(--wf-type-weight, 400);
  line-height: 1.25;
  letter-spacing: 0;
  text-transform: uppercase;
  text-decoration: none;
}
.wf-action-link__star {
  display: inline-flex;
  opacity: 0;
  transition: opacity var(--wf-motion-hover, 180ms) var(--wf-ease, cubic-bezier(0.333333, 0, 0.666667, 1));
}
.wf-action-link:hover .wf-action-link__star,
.wf-action-link:focus-visible .wf-action-link__star {
  opacity: 1;
}
.wf-action-link:focus-visible {
  outline: var(--wf-focus-width, 1px) solid currentColor;
  outline-offset: var(--wf-focus-offset, 3px);
}
[data-theme="night"] .wf-action-link:hover,
[data-theme="night"] .wf-action-link:focus-visible {
  color: var(--wf-night-bright, #ffffff);
}

.wf-menu-trigger {
  appearance: none;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--wf-moonlight, rgba(255, 255, 255, 0.95));
  font-family: var(--wf-font-mono, ui-monospace, monospace);
  font-size: 0.9375rem;
  font-weight: var(--wf-type-weight, 400);
  line-height: 1.25;
  letter-spacing: 0;
  text-transform: uppercase;
  cursor: pointer;
  transition: color var(--wf-motion-hover, 180ms) var(--wf-ease, cubic-bezier(0.333333, 0, 0.666667, 1));
}
.wf-menu-trigger:hover,
.wf-menu-trigger[aria-expanded="true"] {
  color: var(--wf-pure-white, #ffffff);
}
.wf-menu-trigger:focus-visible {
  outline: var(--wf-focus-width, 1px) solid currentColor;
  outline-offset: var(--wf-focus-offset, 3px);
}
.wf-menu-panel {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: var(--wf-space-sm, 8px);
  margin: 0;
  padding: var(--wf-space-md, 10px) 0 0;
  list-style: none;
}
.wf-menu-panel[hidden] {
  display: none;
}
.wf-menu-link {
  color: inherit;
  font-family: var(--wf-font-mono, ui-monospace, monospace);
  font-size: 0.9375rem;
  font-weight: var(--wf-type-weight, 400);
  line-height: 1.25;
  letter-spacing: 0;
  text-transform: uppercase;
  text-decoration: none;
}
.wf-menu-link:hover,
.wf-menu-link:focus-visible {
  color: var(--wf-pure-white, #ffffff);
  text-decoration-line: underline;
  text-decoration-style: dotted;
  text-decoration-thickness: 0.06em;
  text-underline-offset: 0.14em;
}
@media (max-width: 800px) {
  .wf-menu-panel:not([hidden]) {
    position: fixed;
    inset: 0;
    align-items: flex-start;
    justify-content: center;
    gap: var(--wf-space-lg, 16px);
    padding: var(--wf-frame-block, 40px) var(--wf-space-block, 28px);
    background: var(--wf-paper, #faf9f6);
    color: var(--wf-ink, #353431);
    z-index: var(--wf-z-frame, 3);
  }
  .wf-menu-link {
    display: flex;
    align-items: center;
    min-height: var(--wf-tap-target, 44px);
  }
}

.wf-project-card {
  display: grid;
  gap: var(--wf-space-xs, 6px);
  padding: var(--wf-space-lg, 16px) 0;
  border-top: 1px solid var(--wf-hairline, rgba(39, 37, 34, 0.18));
  color: var(--wf-ink, #353431);
  font-family: var(--wf-font-serif, Georgia, serif);
  text-decoration: none;
}
.wf-project-card__title {
  font-size: 1.25rem;
  font-style: italic;
  font-weight: var(--wf-type-weight, 400);
  line-height: 1.15;
}
.wf-project-card__meta {
  color: var(--wf-muted-ink, rgba(25, 24, 22, 0.6));
  font-family: var(--wf-font-mono, ui-monospace, monospace);
  font-size: 0.8125rem;
  letter-spacing: 0;
  text-transform: uppercase;
}
.wf-project-card__summary {
  font-size: 1rem;
  line-height: 1.6;
}
.wf-project-card:hover .wf-project-card__title,
.wf-project-card:focus-visible .wf-project-card__title {
  text-decoration-line: underline;
  text-decoration-style: dotted;
  text-decoration-thickness: 0.06em;
  text-underline-offset: 0.14em;
}
.wf-project-card:focus-visible {
  outline: var(--wf-focus-width, 1px) solid currentColor;
  outline-offset: var(--wf-focus-offset, 3px);
}

.wf-post-row {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  column-gap: 0.6em;
  row-gap: var(--wf-space-xs, 6px);
  align-items: baseline;
  padding: var(--wf-space-sm, 8px) 0;
  color: var(--wf-ink, #353431);
  text-decoration: none;
}
.wf-post-row__date {
  color: var(--wf-muted-ink, rgba(25, 24, 22, 0.6));
  font-family: var(--wf-font-mono, ui-monospace, monospace);
  font-size: 0.9375rem;
  line-height: 1.6;
}
.wf-post-row__title {
  font-family: var(--wf-font-serif, Georgia, serif);
  font-size: 1.25rem;
  font-style: italic;
  font-weight: var(--wf-type-weight, 400);
  line-height: 1.15;
}
.wf-post-row__star {
  display: inline-flex;
  margin-inline-start: var(--wf-space-sm, 8px);
  opacity: 0;
  transition: opacity var(--wf-motion-hover, 180ms) var(--wf-ease, cubic-bezier(0.333333, 0, 0.666667, 1));
}
.wf-post-row:hover .wf-post-row__star,
.wf-post-row:focus-visible .wf-post-row__star {
  opacity: 1;
}
.wf-post-row:focus-visible {
  outline: var(--wf-focus-width, 1px) solid currentColor;
  outline-offset: var(--wf-focus-offset, 3px);
}
[data-theme="night"] .wf-post-row:hover .wf-post-row__title {
  color: var(--wf-night-bright, #ffffff);
}
@media (max-width: 520px) {
  .wf-post-row {
    grid-template-columns: minmax(0, 1fr);
  }
}

.wf-disclosure {
  border-top: 1px solid var(--wf-hairline, rgba(39, 37, 34, 0.18));
  color: var(--wf-ink, #353431);
}
.wf-disclosure__summary {
  display: flex;
  align-items: center;
  gap: var(--wf-space-sm, 8px);
  padding: 7px 0;
  font-family: var(--wf-font-serif, Georgia, serif);
  font-size: 1.25rem;
  font-style: italic;
  font-weight: var(--wf-type-weight, 400);
  line-height: 1.15;
  cursor: pointer;
  list-style: none;
}
.wf-disclosure__summary::marker {
  content: "";
}
.wf-disclosure__summary:focus-visible {
  outline: var(--wf-focus-width, 1px) solid currentColor;
  outline-offset: var(--wf-focus-offset, 3px);
}
.wf-disclosure__chevron {
  flex: none;
  transition: transform var(--wf-motion-hover, 180ms) var(--wf-ease, cubic-bezier(0.333333, 0, 0.666667, 1));
}
.wf-disclosure[open] .wf-disclosure__chevron {
  transform: rotate(180deg);
}
.wf-disclosure__body {
  margin: 0;
  padding: 0 0 var(--wf-space-block, 28px);
  font-family: var(--wf-font-serif, Georgia, serif);
  font-size: clamp(1.125rem, 1.05rem + 0.375vw, 1.25rem);
  font-weight: var(--wf-type-weight, 400);
  line-height: 1.6;
}

.wf-subscribe {
  display: flex;
  align-items: baseline;
  gap: var(--wf-space-xs, 6px);
  color: var(--wf-ink, #353431);
}
.wf-subscribe__input {
  field-sizing: content;
  min-width: 17ch;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: inherit;
  font-family: var(--wf-font-mono, ui-monospace, monospace);
  font-size: 0.9375rem;
  font-weight: var(--wf-type-weight, 400);
  line-height: 1.6;
  caret-color: var(--wf-ink, #353431);
}
.wf-subscribe__input::placeholder {
  color: var(--wf-muted-ink, rgba(25, 24, 22, 0.6));
}
.wf-subscribe__input:focus-visible {
  outline: var(--wf-focus-width, 1px) solid currentColor;
  outline-offset: var(--wf-focus-offset, 3px);
}
.wf-subscribe__enter {
  color: var(--wf-muted-ink, rgba(25, 24, 22, 0.6));
  opacity: 0;
  transition: opacity var(--wf-motion-hover, 180ms) var(--wf-ease, cubic-bezier(0.333333, 0, 0.666667, 1));
}
.wf-subscribe__input:not(:placeholder-shown) ~ .wf-subscribe__enter {
  opacity: 1;
}

.wf-lang {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-end;
}
.wf-lang__trigger {
  appearance: none;
  margin: 0;
  padding: var(--wf-space-xs, 6px) var(--wf-space-md, 10px);
  border: 0;
  background: transparent;
  color: var(--wf-moonlight, rgba(255, 255, 255, 0.95));
  font-family: var(--wf-font-mono, ui-monospace, monospace);
  font-size: 0.9375rem;
  font-weight: var(--wf-type-weight, 400);
  line-height: 1.25;
  letter-spacing: 0;
  text-transform: uppercase;
  cursor: pointer;
  transition: color var(--wf-motion-hover, 180ms) var(--wf-ease, cubic-bezier(0.333333, 0, 0.666667, 1));
}
.wf-lang__trigger:hover,
.wf-lang__trigger[aria-expanded="true"] {
  color: var(--wf-pure-white, #ffffff);
}
.wf-lang__trigger:focus-visible {
  outline: var(--wf-focus-width, 1px) solid currentColor;
  outline-offset: var(--wf-focus-offset, 3px);
}
.wf-lang-menu {
  width: 160px;
  margin: 0 0 var(--wf-space-sm, 8px);
  padding: var(--wf-space-xs, 6px) 0;
  list-style: none;
  border-radius: 4px;
  background: var(--wf-chrome-scrim, rgba(30, 30, 30, 0.95));
  backdrop-filter: blur(10px);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  font-family: var(--wf-font-mono, ui-monospace, monospace);
  font-size: 0.9375rem;
  line-height: 1.4;
}
.wf-lang-menu li {
  margin: 0;
  padding: 0;
  list-style: none;
}
.wf-lang-item {
  display: grid;
  grid-template-columns: 8px minmax(0, 1fr) auto;
  column-gap: var(--wf-space-sm, 8px);
  align-items: center;
  width: 100%;
  margin: 0;
  padding: var(--wf-space-sm, 8px) var(--wf-space-lg, 16px);
  border: 0;
  background: transparent;
  color: var(--wf-moonlight, rgba(255, 255, 255, 0.95));
  font: inherit;
  font-size: 0.9375rem;
  line-height: 1.4;
  text-align: start;
  cursor: pointer;
}
.wf-lang-item:hover {
  background: color-mix(in srgb, var(--wf-pure-white, #ffffff) 10%, transparent);
  color: var(--wf-pure-white, #ffffff);
}
.wf-lang-item[aria-selected="true"] {
  color: var(--wf-night-bright, #ffffff);
}
.wf-lang-item__check {
  opacity: 0;
}
.wf-lang-item[aria-selected="true"] .wf-lang-item__check {
  opacity: 1;
}
.wf-lang-item__code {
  font-size: 0.8125rem;
  text-transform: uppercase;
  opacity: 0.5;
}
